// =================================================================== Thèmes

/// Un thème : palette, arrondis, épaisseur des bordures, ombres, police.
pub struct Theme {
    pub key: &'static str,
    pub name: &'static str,
    pub note: &'static str,
    pub dark: bool,
    pub bg: Color32,
    pub sidebar: Color32,
    pub card: Color32,
    pub card_hi: Color32,
    pub input: Color32,
    pub border: Color32,
    pub text: Color32,
    pub muted: Color32,
    pub faint: Color32,
    pub green: Color32,
    pub orange: Color32,
    pub red: Color32,
    pub blue: Color32,
    /// Couleur d'accent propre au thème (choix « Thème » dans la couleur d'accent).
    pub accent: Color32,
    /// Facteur d'arrondi des angles (1 = arrondi normal, 0 = angles droits).
    pub round: f32,
    /// Épaisseur des bordures de cartes.
    pub stroke: f32,
    /// Ombre douce sous les cartes (surtout pour les thèmes clairs).
    pub shadow: bool,
    /// Texte courant en police à chasse fixe (ambiance écran / terminal).
    pub mono: bool,
}

const fn rgb(r: u8, g: u8, b: u8) -> Color32 {
    Color32::from_rgb(r, g, b)
}

