static THEME_IDX: std::sync::atomic::AtomicUsize = std::sync::atomic::AtomicUsize::new(0);

/// Thème en cours.
pub fn pal() -> &'static Theme {
    &THEMES[THEME_IDX.load(std::sync::atomic::Ordering::Relaxed).min(THEMES.len() - 1)]
}

/// Change le thème en cours (clé inconnue : le premier).
pub fn set_theme(key: &str) {
    let i = THEMES.iter().position(|t| t.key == key).unwrap_or(0);
    THEME_IDX.store(i, std::sync::atomic::Ordering::Relaxed);
}

/// Mélange de deux couleurs (0 = a, 1 = b).
fn mix(a: Color32, b: Color32, t: f32) -> Color32 {
    let l = |x: u8, y: u8| (x as f32 + (y as f32 - x as f32) * t).round() as u8;
    Color32::from_rgb(l(a.r(), b.r()), l(a.g(), b.g()), l(a.b(), b.b()))
}

pub fn accent_color(name: &str) -> Color32 {
    match name {
        "Indigo" => Color32::from_rgb(99, 102, 241),
        "Bleu" => Color32::from_rgb(59, 130, 246),
        "Cyan" => Color32::from_rgb(6, 182, 212),
        "Violet" => Color32::from_rgb(139, 92, 246),
        "Émeraude" => Color32::from_rgb(16, 185, 129),
        "Ambre" => Color32::from_rgb(245, 158, 11),
        "Orange" => Color32::from_rgb(234, 108, 32),
        "Rouge" => Color32::from_rgb(220, 38, 38),
        "Rose" => Color32::from_rgb(236, 72, 153),
        "Ardoise" => Color32::from_rgb(100, 116, 139),
        _ => pal().accent,
    }
}

/// Accent en cours (posé par apply_theme), pour choisir la couleur du texte posé dessus.
static ACCENT_RGB: std::sync::atomic::AtomicU32 = std::sync::atomic::AtomicU32::new(0x6366f1);

/// Couleur de texte lisible sur l'accent : blanc, ou presque noir sur un accent clair.
fn ink() -> Color32 {
    let v = ACCENT_RGB.load(std::sync::atomic::Ordering::Relaxed);
    ink_on(Color32::from_rgb((v >> 16) as u8, (v >> 8) as u8, v as u8))
}

/// Couleur de texte lisible sur un fond donné.
fn ink_on(c: Color32) -> Color32 {
    let (r, g, b) = (c.r() as u32, c.g() as u32, c.b() as u32);
    if 299 * r + 587 * g + 114 * b > 175_000 {
        Color32::from_rgb(18, 18, 18)
    } else {
        Color32::WHITE
    }
}

/// Arrondi d'angle, adapté au thème (angles vifs pour Terminal, très ronds pour Prune…).
fn cr(r: u8) -> CornerRadius {
    CornerRadius::same((r as f32 * pal().round).round().clamp(0.0, 255.0) as u8)
}

/// Police courante à la taille voulue (chasse fixe pour les thèmes Terminal et Ambre).
fn fp(size: f32) -> FontId {
    if pal().mono {
        FontId::monospace(size * 0.93)
    } else {
        FontId::proportional(size)
    }
}

fn semi(size: f32) -> FontId {
    if pal().mono {
        FontId::monospace(size * 0.95)
    } else {
        FontId::new(size, FontFamily::Name("semibold".into()))
    }
}

fn status_color(s: Status) -> Color32 {
    match s {
        Status::Sent => pal().green,
        Status::Quarantine => pal().orange,
        Status::Failed => pal().red,
    }
}

// ================================================================ Types

#[derive(Clone, Copy, PartialEq, Debug)]
enum Level {
    Info,
    Ok,
    Warn,
    Err,
}

impl Level {
    fn color(self) -> Color32 {
        match self {
            Level::Info => pal().blue,
            Level::Ok => pal().green,
            Level::Warn => pal().orange,
            Level::Err => pal().red,
        }
    }
    fn icon(self) -> &'static str {
        match self {
            Level::Info => "ℹ",
            Level::Ok => "✔",
            Level::Warn => "⚠",
            Level::Err => "✖",
        }
    }
    fn tag(self) -> &'static str {
        match self {
            Level::Info => "INFO",
            Level::Ok => "OK",
            Level::Warn => "ALERTE",
            Level::Err => "ERREUR",
        }
    }
}

fn record_message(r: &Record) -> (Level, String) {
    match r.status {
        Status::Sent if !r.reason.is_empty() => (Level::Warn, format!("Envoyé : {} — ⚠ {}", r.release, r.reason)),
        Status::Sent => (Level::Ok, format!("Envoyé : {}", r.release)),
        Status::Quarantine => (Level::Warn, format!("Quarantaine : {} — {}", r.original, r.reason)),
        Status::Failed => (Level::Err, format!("Échec : {} — {}", r.original, r.reason)),
    }
}

