/// Post impossible faute de place : de quoi proposer des solutions.
#[derive(Clone)]
struct PostFail {
    video: PathBuf,
    release: String,
    error: String,
    size: u64,
    /// Dossier (série) : lots, découpage par saison possibles.
    dir: bool,
    seasons: usize,
    /// Disques et place libre, relevés au moment de l'échec.
    drives: Vec<(PathBuf, u64)>,
}

/// Destination d'un envoi.
#[derive(Clone, PartialEq, Debug)]
enum Dest {
    /// Dossier de sortie des réglages (surveillé par le logiciel de post).
    Output,
    /// Renommage sur place, dans le dossier du fichier d'origine.
    InPlace,
    Custom(PathBuf),
}

impl Dest {
    fn dir_for(&self, src: &Path) -> Option<PathBuf> {
        match self {
            Dest::Output => None,
            Dest::InPlace => src.parent().map(Path::to_path_buf),
            Dest::Custom(p) => Some(p.clone()),
        }
    }
    fn label(&self) -> String {
        match self {
            Dest::Output => "Dossier de sortie".into(),
            Dest::InPlace => "Sur place (même dossier)".into(),
            Dest::Custom(p) => format!("Autre : {}", p.display()),
        }
    }
}

/// Nom de release d'un élément du dossier de sortie : nom du fichier sans extension, ou nom
/// complet d'un dossier (« Serie.S01.1080p.x264-TAG » n'a pas d'extension).
fn release_of(p: &Path) -> String {
    if p.is_dir() {
        prep::file_name(p)
    } else {
        p.file_stem().map(|s| s.to_string_lossy().into_owned()).unwrap_or_default()
    }
}

/// Avancement d'un envoi en cours.
#[derive(Clone)]
struct Prog {
    stage: Stage,
    done: u64,
    total: u64,
    started: f64,
}

fn fmt_eta(secs: f64) -> String {
    let s = secs.max(0.0) as u64;
    if s >= 3600 {
        format!("{}h{:02}", s / 3600, (s / 60) % 60)
    } else {
        format!("{}:{:02}", s / 60, s % 60)
    }
}

/// Barre de progression : pourcentage, débit et temps restant pendant la copie.
fn progress_bar(ui: &mut Ui, p: &Prog, now: f64, accent: Color32, width: f32, compact: bool) {
    let (frac, text) = match p.stage {
        Stage::Copy => {
            let f = if p.total == 0 { 0.0 } else { p.done as f32 / p.total as f32 };
            let el = (now - p.started).max(0.001);
            let speed = p.done as f64 / el;
            if compact {
                (f, format!("{:.0} %", f * 100.0))
            } else if p.done > 0 && speed > 0.0 {
                let eta = (p.total.saturating_sub(p.done)) as f64 / speed;
                (f, format!("Copie {:.0} %  ·  {}/s  ·  reste {}", f * 100.0, prep::human_size(speed as u64), fmt_eta(eta)))
            } else {
                (f, format!("Copie {:.0} %", f * 100.0))
            }
        }
        Stage::MediaInfo => (1.0, if compact { "MediaInfo".to_string() } else { "Génération du rapport MediaInfo…".to_string() }),
        Stage::Publish => (1.0, if compact { "Finalisation".to_string() } else { "Finalisation…".to_string() }),
    };
    ui.add(egui::ProgressBar::new(frac).desired_width(width).fill(accent).corner_radius(cr(6)).text(RichText::new(text).color(pal().text).size(12.5)));
}

/// Deux chemins désignent-ils le même dossier ? (casse, / ou \, séparateur final ignorés)
fn same_dir_str(a: &str, b: &str) -> bool {
    let n = |s: &str| s.trim().trim_matches('"').replace('/', "\\").trim_end_matches('\\').to_lowercase();
    !a.trim().is_empty() && n(a) == n(b)
}

/// Ligne « valeur lue dans ngPost.conf » : ✔ si identique au réglage, sinon bouton « Utiliser ».
fn conf_line(ui: &mut Ui, label: &str, key: &str, value: &str, current: &str) -> bool {
    let mut use_it = false;
    ui.horizontal_wrapped(|ui| {
        ui.label(RichText::new(label).color(pal().muted));
        ui.label(RichText::new(value).monospace().color(pal().text));
        ui.label(RichText::new(format!("({key})")).size(11.5).color(pal().faint));
        if same_dir_str(value, current) {
            badge(ui, "✔ identique à ton réglage", pal().green);
        } else {
            if !current.trim().is_empty() {
                badge(ui, "≠ ton réglage", pal().orange);
            }
            if btn_small(ui, "Utiliser").clicked() {
                use_it = true;
            }
        }
    });
    use_it
}

/// Choix de la destination (dossier de sortie, sur place, autre dossier…).
fn dest_picker(ui: &mut Ui, id: &str, dest: &mut Dest, output: &str) {
    let mut pick = false;
    egui::ComboBox::from_id_salt(id).width(260.0).selected_text(dest.label()).show_ui(ui, |ui| {
        let out = if output.trim().is_empty() { "Dossier de sortie (non réglé)".to_string() } else { format!("Dossier de sortie : {}", output.trim()) };
        ui.selectable_value(dest, Dest::Output, out);
        ui.selectable_value(dest, Dest::InPlace, "Sur place : renommer dans le dossier d'origine");
        if ui.selectable_label(matches!(dest, Dest::Custom(_)), "Autre dossier…").clicked() {
            pick = true;
        }
    });
    if pick {
        if let Some(p) = rfd::FileDialog::new().pick_folder() {
            *dest = Dest::Custom(p);
        }
    }
}

