/// Texte en minuscules sans accents.
fn fold(s: &str) -> String {
    s.to_lowercase()
        .chars()
        .map(|c| match c {
            'à' | 'â' | 'ä' | 'á' => 'a',
            'é' | 'è' | 'ê' | 'ë' => 'e',
            'î' | 'ï' | 'í' => 'i',
            'ô' | 'ö' | 'ó' => 'o',
            'ù' | 'û' | 'ü' | 'ú' => 'u',
            'ç' => 'c',
            'ÿ' => 'y',
            c => c,
        })
        .collect::<String>()
        .replace('œ', "oe")
}

/// Tous les mots de la recherche (début de mot, sans accents ni majuscules) sont dans la carte.
fn settings_match(q: &str, title: &str, keys: &str) -> bool {
    // « §Indexers » : cette section seulement (liens « Régler » des autres pages)
    if let Some(t) = q.strip_prefix('§') {
        return fold(title) == fold(t.trim());
    }
    let hay: Vec<String> = fold(title).split(|c: char| !c.is_alphanumeric()).chain(keys.split(' ')).map(str::to_string).filter(|w| !w.is_empty()).collect::<Vec<_>>();
    fold(q).split(|c: char| !c.is_alphanumeric() && c != '.').filter(|w| !w.is_empty()).all(|w| hay.iter().any(|h| h.starts_with(w) || (w.len() >= 4 && h.contains(w))))
}

/// Nœud de l'arborescence affichée (dossier ou fichier).
struct TreeNode {
    name: String,
    size: u64,
    files: usize,
    children: Vec<TreeNode>,
    dir: bool,
}

impl TreeNode {
    fn insert(&mut self, parts: &[String], size: u64) {
        self.size += size;
        self.files += 1;
        let Some((first, rest)) = parts.split_first() else { return };
        if rest.is_empty() {
            self.children.push(TreeNode { name: first.clone(), size, files: 1, children: Vec::new(), dir: false });
            return;
        }
        let i = match self.children.iter().position(|c| c.dir && &c.name == first) {
            Some(i) => i,
            None => {
                self.children.push(TreeNode { name: first.clone(), size: 0, files: 0, children: Vec::new(), dir: true });
                self.children.len() - 1
            }
        };
        self.children[i].insert(rest, size);
    }
    /// Dossiers d'abord, puis fichiers, par ordre alphabétique (naturel pour E01, E02…).
    fn sort(&mut self) {
        self.children.sort_by(|a, b| b.dir.cmp(&a.dir).then_with(|| a.name.to_lowercase().cmp(&b.name.to_lowercase())));
        for c in &mut self.children {
            c.sort();
        }
    }
}

fn file_icon(name: &str) -> &'static str {
    let ext = name.rsplit('.').next().unwrap_or("").to_lowercase();
    match ext.as_str() {
        "mkv" | "mp4" | "avi" | "m2ts" | "ts" | "mov" | "wmv" => "🎞",
        "flac" | "mp3" | "m4a" | "aac" | "ogg" | "opus" | "wav" => "🎵",
        "epub" | "pdf" | "mobi" | "azw3" => "📚",
        "cbz" | "cbr" | "cb7" => "📖",
        "iso" | "bin" | "img" | "nsp" | "xci" | "dmg" => "💾",
        "exe" | "msi" => "🎮",
        _ => "📄",
    }
}

/// Arborescence de ce que reçoit celui qui télécharge : dossiers repliables, traits de liaison,
/// tailles et nombre de fichiers. `files` : (chemin relatif dans la release, taille).
/// `flat` : post sans compression (fichiers à plat, sans dossiers).
fn tree_view(ui: &mut Ui, id: &str, release: &str, files: &[(PathBuf, u64)], flat: bool, accent: Color32) {
    let mut root = TreeNode { name: release.to_string(), size: 0, files: 0, children: Vec::new(), dir: true };
    for (rel, size) in files {
        let parts: Vec<String> = if flat {
            vec![prep::file_name(rel)]
        } else {
            rel.components().map(|c| c.as_os_str().to_string_lossy().into_owned()).collect()
        };
        root.insert(&parts, *size);
    }
    root.sort();
    let caption = if flat {
        "Post sans compression : les fichiers arrivent un par un, sans sous-dossiers. Le logiciel de téléchargement les range dans un dossier au nom du NZB :"
    } else {
        "Dans le NZB : une archive (avec ses fichiers de réparation par2). Une fois extraite, dans le dossier que le logiciel de téléchargement crée au nom du NZB :"
    };
    ui.label(RichText::new(caption).size(12.0).color(pal().muted));
    ui.add_space(4.0);
    Frame::new().fill(pal().input).stroke(Stroke::new(1.0_f32, pal().border)).corner_radius(cr(10)).inner_margin(Margin::symmetric(12, 8)).show(ui, |ui| {
        ui.set_width(ui.available_width());
        ui.spacing_mut().item_spacing = vec2(6.0, 0.0);
        tree_rows(ui, &format!("{id}/"), &root, 0, accent, true);
    });
}

fn tree_rows(ui: &mut Ui, path: &str, n: &TreeNode, depth: usize, accent: Color32, open_default: bool) {
    const STEP: f32 = 20.0;
    const ROW: f32 = 24.0;
    const MAX_FILES: usize = 8;
    let id = ui.make_persistent_id(path);
    let mut open = ui.ctx().data_mut(|d| *d.get_temp_mut_or(id, open_default));
    let (rect, resp) = ui.allocate_exact_size(vec2(ui.available_width(), ROW), if n.dir && depth > 0 { Sense::click() } else { Sense::hover() });
    let p = ui.painter();
    if resp.hovered() {
        p.rect_filled(rect, cr(6), pal().card_hi);
    }
    // traits de liaison : une ligne par niveau, et un coude vers l'élément
    let guide = Stroke::new(1.0_f32, pal().border.lerp_to_gamma(pal().muted, 0.25));
    for lvl in 1..=depth {
        let x = rect.left() + (lvl as f32 - 0.5) * STEP;
        let y1 = if lvl == depth { rect.center().y } else { rect.bottom() };
        p.line_segment([egui::pos2(x, rect.top()), egui::pos2(x, y1)], guide);
    }
    if depth > 0 {
        let x = rect.left() + (depth as f32 - 0.5) * STEP;
        p.line_segment([egui::pos2(x, rect.center().y), egui::pos2(x + STEP * 0.4, rect.center().y)], guide);
    }
    let mut x = rect.left() + depth as f32 * STEP;
    if n.dir && depth > 0 {
        p.text(egui::pos2(x + 5.0, rect.center().y), Align2::CENTER_CENTER, if open { "▼" } else { "▶" }, fp(9.0), pal().muted);
        x += 12.0;
    }
    let icon = if depth == 0 { "📦" } else if n.dir { "📁" } else { file_icon(&n.name) };
    p.text(egui::pos2(x + 9.0, rect.center().y), Align2::CENTER_CENTER, icon, fp(14.0), if n.dir { accent } else { pal().muted });
    x += 22.0;
    let right = if n.dir { format!("{} fichier(s) · {}", n.files, prep::human_size(n.size)) } else { prep::human_size(n.size) };
    let rw = p.layout_no_wrap(right.clone(), fp(12.0), pal().faint).size().x;
    let name_w = (rect.right() - rw - 16.0 - x).max(40.0);
    let font = if n.dir { semi(13.5) } else { egui::FontId::monospace(12.5) };
    let galley = ui.painter().layout(n.name.clone(), font, if depth == 0 { accent } else { pal().text }, name_w);
    let g = if galley.rows.len() > 1 {
        // nom trop long : coupé avec « … »
        let mut t = n.name.clone();
        while t.chars().count() > 4 && ui.painter().layout_no_wrap(format!("{t}…"), if n.dir { semi(13.5) } else { egui::FontId::monospace(12.5) }, pal().text).size().x > name_w {
            t.pop();
        }
        ui.painter().layout_no_wrap(format!("{t}…"), if n.dir { semi(13.5) } else { egui::FontId::monospace(12.5) }, if depth == 0 { accent } else { pal().text })
    } else {
        galley
    };
    let p = ui.painter();
    p.galley(egui::pos2(x, rect.center().y - g.size().y / 2.0), g, pal().text);
    p.text(egui::pos2(rect.right() - 6.0, rect.center().y), Align2::RIGHT_CENTER, right, fp(12.0), pal().faint);
    if resp.clicked() {
        open = !open;
        ui.ctx().data_mut(|d| d.insert_temp(id, open));
    }
    if !n.dir || (depth > 0 && !open) {
        return;
    }
    // dossiers ouverts par défaut sur deux niveaux ; au-delà de 8 fichiers, le reste est replié
    let more_id = ui.make_persistent_id(format!("{path}+"));
    let show_all = ui.ctx().data_mut(|d| *d.get_temp_mut_or(more_id, false));
    let mut files_shown = 0;
    let hidden: Vec<&TreeNode> = n.children.iter().filter(|c| !c.dir).skip(MAX_FILES).collect();
    for c in &n.children {
        if !c.dir {
            if files_shown >= MAX_FILES && !show_all {
                continue;
            }
            files_shown += 1;
        }
        tree_rows(ui, &format!("{path}{}/", c.name), c, depth + 1, accent, depth < 1);
    }
    if !hidden.is_empty() && !show_all {
        let size: u64 = hidden.iter().map(|c| c.size).sum();
        let (r, resp) = ui.allocate_exact_size(vec2(ui.available_width(), ROW), Sense::click());
        let x = r.left() + (depth + 1) as f32 * STEP + 34.0;
        let col = if resp.hovered() { accent } else { pal().muted };
        ui.painter().text(egui::pos2(x, r.center().y), Align2::LEFT_CENTER, format!("… et {} autre(s) fichier(s) ({}) — afficher", hidden.len(), prep::human_size(size)), fp(12.0), col);
        if resp.on_hover_cursor(egui::CursorIcon::PointingHand).clicked() {
            ui.ctx().data_mut(|d| d.insert_temp(more_id, true));
        }
    }
}

/// Requête envoyée à l'indexer, construite comme au vrai dépôt (clé masquée) : un film et une
/// série d'exemple, pour voir la catégorie envoyée et tous les champs.
fn request_preview(ui: &mut Ui, i: &prep::IndexerCfg, rest: bool) {
    ui.label(RichText::new("REQUÊTE ENVOYÉE · telle qu'elle partira (clé masquée)").font(semi(11.0)).color(pal().faint));
    Frame::new().fill(pal().input).stroke(Stroke::new(1.0_f32, pal().border)).corner_radius(cr(8)).inner_margin(Margin::symmetric(10, 8)).show(ui, |ui| {
        ui.set_width(ui.available_width());
        for (k, (label, rel)) in [("Film", "Film.2024.FRENCH.1080p.WEB.x264-GRP"), ("Série", "Ma.Serie.S01.FRENCH.1080p.WEB.H264-GRP")].into_iter().enumerate() {
            if k > 0 {
                ui.add_space(6.0);
            }
            let f = crate::upload::Files {
                nzb: PathBuf::from(format!("{rel}.nzb")),
                mediainfo: Some(PathBuf::from(format!("{rel}.xml"))),
                nfo: i.send_nfo.then(|| PathBuf::from(format!("{rel}.nfo"))),
                ..Default::default()
            };
            let (args, key) = if rest {
                let v = i.rest_view();
                (crate::upload::rest_args(&v, &f, rel), i.rest_key_eff().to_string())
            } else {
                (crate::upload::nzbadd_args(i, &f, rel), i.api_key.trim().to_string())
            };
            let cat = crate::upload::category_for(i, rel, &f);
            ui.label(RichText::new(format!("{label} « {rel} » — {}", crate::upload::category_label(&cat))).size(12.5).font(semi(12.5)).color(pal().text));
            for l in crate::upload::describe_args(&args, &key) {
                ui.add(egui::Label::new(RichText::new(l).monospace().size(11.5).color(pal().muted)).wrap());
            }
        }
    });
    ui.label(RichText::new("Le détail de chaque dépôt (requête, réponse complète de l'indexer, catégorie qu'il a attribuée) est dans le Journal et dans logs\\api-date.log.").size(12.0).color(pal().faint));
}

/// Catégories et groupes d'un indexer, à exporter (texte, CSV ou JSON).
fn export_cats(i: &prep::IndexerCfg, fmt: &str) -> String {
    let q = |s: &str| format!("\"{}\"", s.replace('"', "\"\""));
    let js = |s: &str| format!("\"{}\"", s.replace('\\', "\\\\").replace('"', "\\\""));
    match fmt {
        "csv" => {
            let mut o = String::from("\u{feff}type;id;nom\r\n");
            for (id, n) in &i.cat_list {
                o.push_str(&format!("catégorie;{};{}\r\n", q(id), q(n)));
            }
            for g in &i.groups {
                o.push_str(&format!("groupe;;{}\r\n", q(g)));
            }
            o
        }
        "json" => format!(
            "{{\n  \"indexer\": {},\n  \"categories\": [{}],\n  \"groups\": [{}]\n}}\n",
            js(i.name.trim()),
            i.cat_list.iter().map(|(id, n)| format!("\n    {{\"id\": {}, \"name\": {}}}", js(id), js(n))).collect::<Vec<_>>().join(","),
            i.groups.iter().map(|g| js(g)).collect::<Vec<_>>().join(", ")
        ),
        _ => {
            let mut o = format!("{} — catégories ({})\r\n", i.name.trim(), i.cat_list.len());
            for (id, n) in &i.cat_list {
                o.push_str(&format!("{id}\t{n}\r\n"));
            }
            o.push_str(&format!("\r\nGroupes Usenet indexés ({})\r\n", i.groups.len()));
            for g in &i.groups {
                o.push_str(&format!("{g}\r\n"));
            }
            o
        }
    }
}

/// Groupes proposés pour un type de post : un clic ajoute le groupe à la liste.
fn group_chips(ui: &mut Ui, field: &mut String, suggestions: &[&str]) {
    let have: Vec<String> = field.split([',', ';', ' ']).map(|g| g.trim().to_lowercase()).filter(|g| !g.is_empty()).collect();
    ui.horizontal_wrapped(|ui| {
        ui.spacing_mut().item_spacing = vec2(4.0, 4.0);
        for g in suggestions.iter().filter(|g| !have.contains(&g.to_lowercase())) {
            let short = g.trim_start_matches("alt.binaries.");
            let b = egui::Button::new(RichText::new(format!("+ a.b.{short}")).size(11.5).color(pal().muted)).fill(pal().card_hi).stroke(Stroke::new(1.0_f32, pal().border)).corner_radius(cr(6));
            if ui.add(b).on_hover_text(format!("Ajouter {g}")).clicked() {
                if !field.trim().is_empty() {
                    field.push_str(", ");
                }
                field.push_str(g);
            }
        }
    });
}

/// Insère `what` à la position du curseur d'un champ de texte (à la fin s'il n'a jamais eu le focus).
fn insert_at_cursor(ctx: &egui::Context, id: egui::Id, text: &mut String, what: &str) {
    use egui::text::{CCursor, CCursorRange};
    let mut state = egui::text_edit::TextEditState::load(ctx, id).unwrap_or_default();
    let n = text.chars().count();
    let at = state.cursor.char_range().map(|r| r.primary.index.min(n)).unwrap_or(n);
    let byte = text.char_indices().nth(at).map(|(b, _)| b).unwrap_or(text.len());
    text.insert_str(byte, what);
    state.cursor.set_char_range(Some(CCursorRange::one(CCursor::new(at + what.chars().count()))));
    state.store(ctx, id);
    ctx.memory_mut(|m| m.request_focus(id));
}

/// Sections de Réglages masquées en mode Simple (indices de `SETTINGS_INDEX`) : Nommage,
/// Options du post, Serveurs Usenet, e-mail, fichiers de l'application, catégories de contenu.
const EXPERT_SECTIONS: [usize; 6] = [2, 5, 6, 11, 14, 15];

const JF_MANUAL: usize = 0;
const JF_SERIES: usize = 1;
const JF_CONTENT: usize = 2;
const JF_BATCH: usize = 3;

/// NFO et MediaInfo d'un traitement manuel. Les réglages (Réglages → MediaInfo, options de
/// chaque indexer) sont les valeurs par défaut, celles de l'automatique ; ici on les change
/// pour ce traitement seulement. `None` : valeur par défaut.
#[derive(Clone, Debug, PartialEq)]
struct JobFiles {
    nfo_create: Option<bool>,
    nfo_keep: bool,
    nfo_send: bool,
    mi_send: Option<bool>,
    /// Catégorie choisie à la main par indexer : (indexer, id).
    cats: Vec<(String, String)>,
    /// Groupes Usenet choisis pour ce traitement (vide : automatiques).
    groups: String,
    /// Joindre le rapport BDInfo (Blu-ray complet) ; NFO d'un Blu-ray qui a déjà le sien.
    bd_send: Option<bool>,
    nfo_bd: Option<String>,
    /// Textes modifiés avant le traitement : rapport MediaInfo livré, NFO envoyé, BDInfo.
    mi_text: Option<String>,
    nfo_text: Option<String>,
    bd_text: Option<String>,
}

impl JobFiles {
    fn from_cfg(c: &Config) -> Self {
        JobFiles { nfo_create: None, nfo_keep: c.nfo_keep, nfo_send: c.nfo_send, mi_send: None, cats: Vec::new(), groups: String::new(), bd_send: None, nfo_bd: None, mi_text: None, nfo_text: None, bd_text: None }
    }
    /// Config du traitement : les choix faits ici remplacent les valeurs par défaut.
    fn apply(&self, c: &mut Config) {
        c.nfo_keep = self.nfo_keep;
        c.nfo_send = self.nfo_send;
        c.cat_force = self.cats.clone();
        c.groups_force = self.groups.trim().to_string();
        if let Some(v) = self.bd_send {
            c.bdinfo_scan = v;
        }
        if let Some(v) = &self.nfo_bd {
            c.nfo_bd = v.clone();
        }
        c.mi_override = self.mi_text.clone();
        c.nfo_override = self.nfo_text.clone();
        c.bd_override = self.bd_text.clone();
        if let Some(v) = self.nfo_create {
            c.nfo_create = v;
        }
        if let Some(v) = self.mi_send {
            for i in c.indexers.iter_mut() {
                i.send_mi = v;
            }
        }
    }
}

/// Bascule Simple / Expert (barre latérale).
fn mode_switch(ui: &mut Ui, expert: &mut bool, accent: Color32) {
    let w = (ui.available_width() - 4.0) / 2.0;
    ui.horizontal(|ui| {
        ui.spacing_mut().item_spacing.x = 4.0;
        for (on, label, tip) in [
            (false, "🌱 Simple", "L'essentiel : les réglages avancés gardent leurs valeurs par défaut et sont masqués"),
            (true, "🛠 Expert", "Tout : modèles de nom, options du post, serveurs Usenet, rapports MediaInfo, filtres et détail des journaux, catégories de contenu…"),
        ] {
            let sel = *expert == on;
            let b = egui::Button::new(RichText::new(label).size(12.0).color(if sel { ink() } else { pal().muted }))
                .fill(if sel { accent } else { pal().card })
                .stroke(Stroke::new(1.0_f32, if sel { accent } else { pal().border }))
                .corner_radius(cr(8));
            if ui.add_sized([w, 26.0], b).on_hover_text(tip).clicked() {
                *expert = on;
            }
        }
    });
}

