/// NZB à télécharger pour être reposté : fichier ou adresse, nom de release, indexer où il a
/// été trouvé (choix obligatoire, « ailleurs » compris), indexers où le reposter, repost tout
/// seul à la fin ou après validation.
struct DlNew {
    src: String,
    name: String,
    /// « dl » (télécharger seulement), « repost », « reports » (télécharger puis créer seulement
    /// NFO / MediaInfo / BDInfo), « » (pas encore choisi).
    mode: String,
    reports: crate::jobs::ReportsOnly,
    /// Confié au client avec : catégorie, priorité, en pause.
    add: crate::dl::AddOpts,
    source: Option<String>,
    targets: Vec<String>,
    auto: bool,
    /// Traitement choisi avant le téléchargement (NFO, MediaInfo, catégories, suite).
    opts: crate::dl::RepostOpts,
    /// Déjà téléchargé (historique du client) : (identifiant, dossier vu d'ici).
    done: Option<(String, PathBuf)>,
}

impl DlNew {
    /// Tout est choisi pour lancer : le mode, un nom (une adresse peut s'en passer pour un
    /// téléchargement seul), et pour un repost l'origine et au moins un indexer.
    fn ready(&self) -> bool {
        let name = !prep::clean_name(&self.name).is_empty();
        match self.mode.as_str() {
            "dl" => name || self.src.starts_with("http"),
            "reports" => (name || self.src.starts_with("http")) && (self.reports.nfo || self.reports.mediainfo || self.reports.bdinfo),
            "repost" => name && self.source.is_some() && !crate::dl::repost_targets(self.source.as_deref().unwrap_or(""), &self.targets).is_empty(),
            _ => false,
        }
    }
}

/// Reposte un téléchargement terminé : traité comme l'inbox (nom, MediaInfo, NFO…), posté, puis
/// déposé seulement sur les indexers choisis (jamais celui d'origine).
#[allow(clippy::too_many_arguments)]
fn run_repost(w: Worker, cfg: Config, hist: Arc<Mutex<History>>, posts: PostQueue, reps: Arc<Mutex<Vec<crate::dl::Repost>>>, r: crate::dl::Repost, path: PathBuf) {
    thread::spawn(move || {
        let mut c = cfg.clone();
        c.targets = crate::dl::repost_targets(&r.source, &r.targets);
        c.api_upload = true;
        if c.action == "rename" {
            c.action = "post".into();
        }
        // traitement choisi avant le téléchargement
        r.opts.apply(&mut c);
        let how = if c.dl_after == "copy" { Transfer::Copy } else { Transfer::Move };
        let set = |state: &str, note: String, out: Option<Vec<String>>| {
            if let Ok(mut v) = reps.lock() {
                if let Some(x) = v.iter_mut().find(|x| x.id == r.id && x.release == r.release) {
                    x.state = state.into();
                    x.note = note;
                    if let Some(o) = out {
                        x.out = o;
                    }
                }
                crate::dl::save_reposts(&v);
            }
        };
        // rapports seuls (NFO, MediaInfo, BDInfo) : créés à côté du téléchargement, rien d'autre
        if let (Some(want), true) = (r.opts.reports_only(), path.exists()) {
            let res = crate::jobs::reports_only(&cfg, &path, want, None, &mut |l| w.send(Ev::Log(Level::Info, format!("{} : {l}", r.release))));
            match res {
                Ok((made, notes)) => {
                    let list = made.iter().map(|p| prep::file_name(p)).collect::<Vec<_>>().join(", ");
                    let note = format!("rapports créés : {list}{}", if notes.is_empty() { String::new() } else { format!(" ({})", notes.join(" ; ")) });
                    set("done", note.clone(), None);
                    crate::notify::record(format!("✔ Rapports de {} : {list}", r.release));
                    crate::tray::notify("Rapports créés", &format!("{} : {list}", r.release));
                    w.send(Ev::Log(Level::Ok, format!("{} : {note}", r.release)));
                }
                Err(e) => {
                    set("failed", format!("rapports : {e}"), None);
                    crate::notify::record(format!("✖ Rapports de {} : {e}", r.release));
                    w.send(Ev::Log(Level::Err, format!("Rapports de {} : {e}", r.release)));
                }
            }
            return;
        }
        if !path.exists() {
            let why = format!("dossier du téléchargement introuvable d'ici : {} (page Téléchargements → réglages du client : dossiers du client vus d'ici)", path.display());
            set("failed", why.clone(), None);
            crate::notify::record(format!("✖ Repost de {} : {why}", r.release));
            w.send(Ev::Log(Level::Err, format!("Repost de {} : {why}", r.release)));
            return;
        }
        w.send(Ev::Log(Level::Info, format!("Repost de {} vers {} : traitement de {}", r.release, c.targets.join(", "), path.display())));
        let recs = jobs::process_path(&path, &c, how, Some(&r.release), &hist, &mut |st, d, t| w.send(Ev::Progress(path.clone(), st, d, t)));
        let ok: Vec<String> = recs.iter().filter(|x| x.status == Status::Sent).map(|x| x.release.clone()).collect();
        for rec in &recs {
            if rec.status == Status::Sent && c.post_mode == "cli" && !c.ngpost_exe.trim().is_empty() {
                queue_post(&posts, &hist, true, PathBuf::from(&rec.dest), rec.release.clone());
            }
            w.send(Ev::WatchRecord(rec.clone()));
        }
        if recs.is_empty() || ok.len() < recs.len() {
            let why = recs.iter().find(|x| x.status != Status::Sent).map(|x| x.reason.clone()).unwrap_or_else(|| "rien à traiter dans le téléchargement".into());
            set("failed", format!("{why}{REPOST_DIR}{}", path.display()), Some(ok.clone()));
            crate::notify::record(format!("✖ Repost de {} : {why}", r.release));
            crate::tray::notify("Repost en échec", &format!("{} : {why}", r.release));
        } else {
            set("done", format!("préparée : {} → {}", ok.join(", "), c.targets.join(", ")), Some(ok.clone()));
            crate::notify::record(format!("↻ Reposté (préparé) : {} → {}", ok.join(", "), c.targets.join(", ")));
            crate::tray::notify("Repost préparé", &format!("{} → post puis dépôt sur {}", ok.join(", "), c.targets.join(", ")));
        }
    });
}

/// Séparateur, dans la note d'un repost en échec, entre la raison et le dossier téléchargé.
const REPOST_DIR: &str = " · dossier : ";

/// Dossier téléchargé d'un repost (note = le dossier, ou « raison · dossier : … ») s'il existe.
fn repost_dir(note: &str) -> Option<PathBuf> {
    let p = note.rsplit_once(REPOST_DIR).map(|(_, p)| p).unwrap_or(note).trim();
    (!p.is_empty() && Path::new(p).exists()).then(|| PathBuf::from(p))
}

/// Étapes d'un parcours (numérotées, reliées par des flèches) : titre et précision de chacune.
/// `current` (1 à n) : l'étape en cours ; avant elle, faites (✔) ; None : simple légende.
fn flow_bar(ui: &mut Ui, steps: &[(&str, &str)], current: Option<usize>, accent: Color32) {
    ui.horizontal_wrapped(|ui| {
        ui.spacing_mut().item_spacing = vec2(6.0, 6.0);
        for (k, (t, d)) in steps.iter().enumerate() {
            let n = k + 1;
            let (state_col, mark) = match current {
                Some(c) if n < c => (pal().green, "✔".to_string()),
                Some(c) if n == c => (accent, n.to_string()),
                Some(_) => (pal().faint, n.to_string()),
                None => (accent, n.to_string()),
            };
            // largeur de l'étape connue d'avance : passe à la ligne entière plutôt que de
            // s'écraser en fin de ligne (texte vertical)
            let tw = ui.fonts(|f| f.layout_no_wrap(t.to_string(), semi(12.5), Color32::WHITE).size().x);
            let dw = ui.fonts(|f| f.layout_no_wrap(d.to_string(), FontId::proportional(11.0), Color32::WHITE).size().x);
            let need = tw.max(dw) + 20.0 + 8.0 + 22.0 + 4.0;
            if k > 0 && ui.available_width() < need {
                ui.end_row();
            }
            Frame::new().fill(state_col.gamma_multiply(0.10)).stroke(Stroke::new(1.0_f32, state_col.gamma_multiply(0.5))).corner_radius(cr(10)).inner_margin(Margin::symmetric(10, 6)).show(ui, |ui| {
                ui.horizontal(|ui| {
                    let (r, _) = ui.allocate_exact_size(vec2(20.0, 20.0), Sense::hover());
                    ui.painter().circle_filled(r.center(), 10.0, state_col);
                    ui.painter().text(r.center(), Align2::CENTER_CENTER, &mark, semi(11.5), ink());
                    ui.vertical(|ui| {
                        ui.spacing_mut().item_spacing.y = 0.0;
                        ui.add(egui::Label::new(RichText::new(*t).font(semi(12.5)).color(pal().text)).extend());
                        if !d.is_empty() {
                            ui.add(egui::Label::new(RichText::new(*d).size(11.0).color(pal().muted)).extend());
                        }
                    });
                });
            });
            if n < steps.len() {
                ui.label(RichText::new("→").size(14.0).color(pal().faint));
            }
        }
    });
}

// ------------------------------------------------------------------ fenêtres surgissantes

/// Ton d'une ligne ou d'une fenêtre.
#[derive(Clone, Copy, PartialEq, Debug)]
enum Tone {
    Normal,
    Good,
    Warn,
    Bad,
}

impl Tone {
    fn color(self) -> Color32 {
        match self {
            Tone::Normal => pal().text,
            Tone::Good => pal().green,
            Tone::Warn => pal().orange,
            Tone::Bad => pal().red,
        }
    }
}

/// Traitement manuel à lancer une fois le récapitulatif confirmé.
#[derive(Clone, Copy, PartialEq, Debug)]
enum SendKind {
    Manual,
    Batch,
    BatchSeries,
    BatchOthers,
    Series,
    Content,
}

/// Ce que fait un bouton de fenêtre surgissante.
#[derive(Clone, PartialEq, Debug)]
enum PopAct {
    Close,
    Go(Page),
    Settings(String),
    Send(SendKind),
    DlResumeAll,
    DlForce(String),
    DlOpenWeb,
    ChooseNzbApp,
    /// Poster sans revérifier une release trouvée déjà présente (vidéo, release).
    ForcePost(PathBuf, String),
    /// Déposer les releases écartées comme déjà présentes (page Envoyer des NZB).
    ZForceDeposit,
    /// Ouvre le réglage de l'envoi d'un indexer (et sa zone « documentation »).
    IdxEdit(String),
    /// Cherche l'adresse d'envoi d'un indexer (lectures, sans clé ni fichier).
    IdxProbe(String),
    /// Auto-configuration d'un indexer avec son adresse et sa clé.
    IdxAuto(String),
    /// Donne ce nom au champ du NZB de cet indexer.
    IdxField(String, String),
}

/// Bloc numéroté d'un récapitulatif : titre et lignes (libellé, valeur, ton).
#[derive(Clone, Debug)]
struct PopBlock {
    title: String,
    rows: Vec<(String, String, Tone)>,
}

/// Point à vérifier : bloquant ou non, texte, correction proposée.
#[derive(Clone, Debug)]
struct PopIssue {
    blocking: bool,
    text: String,
    fix: Option<(String, PopAct)>,
}

/// Fenêtre surgissante : explication, avertissement, ou récapitulatif avant un traitement.
#[derive(Clone, Debug)]
struct Popup {
    icon: &'static str,
    title: String,
    intro: String,
    tone: Tone,
    blocks: Vec<PopBlock>,
    issues: Vec<PopIssue>,
    /// (libellé, action, principal) ; un bouton principal est désactivé s'il reste un point
    /// bloquant et que son action lance quelque chose.
    actions: Vec<(String, PopAct, bool)>,
}

impl Popup {
    fn info(icon: &'static str, title: impl Into<String>, intro: impl Into<String>, tone: Tone) -> Popup {
        Popup { icon, title: title.into(), intro: intro.into(), tone, blocks: Vec::new(), issues: Vec::new(), actions: vec![("Fermer".into(), PopAct::Close, false)] }
    }
}

/// NFO d'origine d'un élément : dans le dossier (ou un sous-dossier direct), sinon à côté du fichier.
fn origin_nfo(p: &Path) -> Option<PathBuf> {
    let is_nfo = |x: &Path| x.extension().map(|e| e.eq_ignore_ascii_case("nfo")).unwrap_or(false);
    if p.is_dir() {
        let rd: Vec<PathBuf> = std::fs::read_dir(p).ok()?.flatten().map(|e| e.path()).collect();
        if let Some(n) = rd.iter().find(|x| x.is_file() && is_nfo(x)) {
            return Some(n.clone());
        }
        return rd.iter().filter(|x| x.is_dir()).find_map(|d| std::fs::read_dir(d).ok().and_then(|r| r.flatten().map(|e| e.path()).find(|x| x.is_file() && is_nfo(x))));
    }
    jobs::nfo_near(p).or_else(|| crate::content::sibling_nfo(p))
}

/// Serveurs Usenet du post, en détail : ceux gérés ici, sinon ceux lus dans ngPost.conf.
fn recap_servers(c: &Config, conf: Option<&ngpost::NgConf>) -> Vec<(String, String, Tone)> {
    let mut rows = Vec::new();
    let (servers, from): (Vec<crate::usenet::Server>, String) = if c.usenet_managed {
        (c.usenet_servers.iter().filter(|s| !s.host.trim().is_empty()).cloned().collect(), "Réglages → Serveurs Usenet".into())
    } else {
        match conf {
            Some(cf) => {
                let text = std::fs::read(&cf.path).map(|b| ngpost::decode_text(&b)).unwrap_or_default();
                (crate::usenet::parse_conf_servers(&text), format!("ngPost.conf ({})", cf.path.display()))
            }
            None => (Vec::new(), "ngPost.conf introuvable".into()),
        }
    };
    rows.push(("Serveurs".into(), format!("{} serveur(s), d'après {from}", servers.len()), if servers.is_empty() { Tone::Bad } else { Tone::Normal }));
    let on: Vec<&crate::usenet::Server> = servers.iter().filter(|s| s.enabled).collect();
    for (n, s) in servers.iter().enumerate() {
        let conn = if s.connections > 0 { s.connections } else { 0 };
        let mut d = s.describe_with(conn);
        if conn == 0 {
            d = d.replace(" · 0 connexion(s)", " · connexions par défaut de NgPost");
        }
        if c.usenet_managed && c.usenet_auto_best && on.len() > 1 && s.solo() != s.connections && s.enabled {
            d.push_str(&format!(" · {} connexion(s) s'il est utilisé seul", s.solo()));
        }
        rows.push((format!("   serveur {}", n + 1), d, if s.enabled { Tone::Normal } else { Tone::Warn }));
    }
    let total: u32 = on.iter().map(|s| s.connections).sum();
    let conns = if c.usenet_managed && c.usenet_auto_best && on.len() > 1 {
        let solos: Vec<u32> = on.iter().map(|s| s.solo()).collect();
        format!("le plus rapide des {} serveurs activés, testé juste avant le post, est utilisé seul : {} à {} connexions selon celui retenu{}", on.len(), solos.iter().min().unwrap_or(&0), solos.iter().max().unwrap_or(&0), if on.iter().any(|s| s.nzb_check) { " (+ le serveur de vérification des articles)" } else { "" })
    } else if on.is_empty() {
        "aucun serveur activé".into()
    } else {
        format!("{total} connexion(s) en même temps sur {} serveur(s) activé(s)", on.len())
    };
    rows.push(("Connexions".into(), conns, if on.is_empty() { Tone::Bad } else { Tone::Normal }));
    if !c.usenet_managed && c.ng_threads == 0 {
        if let Some(t) = conf.and_then(|cf| cf.get("THREAD")) {
            let _ = t;
        }
    }
    rows
}

/// Titre du bloc « présence sur les indexers » du récapitulatif (rempli en arrière-plan).
const RECAP_DUPE: &str = "Déjà sur les indexers ?";

/// Releases d'un récapitulatif à chercher : (release, noms cherchés), 20 au plus (les autres
/// sont vérifiées au moment de leur post).
fn recap_dupe_jobs(r: &RecapIn) -> Vec<(String, Vec<String>)> {
    let mut v = Vec::new();
    for (n, (_, rels, _)) in r.items.iter().enumerate() {
        for rel in rels.split(" + ").map(str::trim).filter(|x| !x.is_empty()) {
            // nom d'origine : celui du fichier ou du dossier (séries : pas de nom d'origine par release)
            let origins = if r.series { Vec::new() } else { r.sources.get(n).map(|p| vec![prep::file_name(p)]).unwrap_or_default() };
            v.push((rel.to_string(), crate::search::names_for(rel, &origins)));
        }
    }
    v.truncate(20);
    v
}

/// Ce qui sera fait d'une release selon les recherches : texte et ton.
fn dupe_verdict(cfg: &Config, rel: &str, names: &[String], res: &[crate::search::Lookup]) -> (String, Tone) {
    use crate::search::Found;
    let mut parts = Vec::new();
    let mut present = Vec::new();
    for l in res {
        let (m, t) = match &l.found {
            Found::Exact(_) => {
                present.push(l.indexer.clone());
                ("⚠", "déjà présente")
            }
            Found::Similar(_) => ("ℹ", "absente (versions proches)"),
            Found::Absent => ("✔", "absente"),
            Found::Unknown(_) if cfg.indexers.iter().find(|i| i.name.trim() == l.indexer).and_then(crate::search::method).is_none() => ("–", "non vérifiée (pas de recherche réglée)"),
            Found::Unknown(_) => ("?", "vérification impossible (postée quand même)"),
        };
        parts.push(format!("{} {m} {t}", l.indexer));
    }
    let renamed = names.len() > 1 || names.first().map(|n| n != rel).unwrap_or(false);
    let name = if renamed { format!("postée sous « {rel} »") } else { format!("postée sous son nom « {rel} »") };
    let all = !res.is_empty() && present.len() == res.len();
    let next = if present.is_empty() {
        name
    } else if cfg.dupe_check == "warn" {
        format!("{name} quand même (signaler seulement)")
    } else if all {
        "ne sera pas postée (déjà présente partout) — « Poster quand même » proposé".into()
    } else {
        format!("{name}, sauf pour {}", present.join(", "))
    };
    let also = if names.len() > 1 { format!(" (cherchée aussi sous {})", names[1..].iter().map(|n| format!("« {n} »")).collect::<Vec<_>>().join(", ")) } else { String::new() };
    (format!("{}{also} → {next}", parts.join(" · ")), if present.is_empty() { Tone::Good } else { Tone::Warn })
}

/// Points d'attention communs à tous les traitements manuels.
fn send_issues(cfg: &Config, action: &str, targets: &[String], dest: Option<&Path>, releases: &[String], hist: Option<&history::History>, force_dup: bool) -> Vec<PopIssue> {
    let mut v = Vec::new();
    let settings = |q: &str| Some(("Ouvrir le réglage".to_string(), PopAct::Settings(q.into())));
    if let Some(why) = plan_problem(action, targets, cfg) {
        v.push(PopIssue { blocking: true, fix: settings(if why.contains("ngPost") { "ngpost.exe" } else { "indexers" }), text: why });
    }
    if dest.is_none() {
        if let Err(e) = cfg.ready_send() {
            v.push(PopIssue { blocking: true, text: format!("Dossier de sortie : {e}"), fix: settings("dossier de sortie") });
        }
    }
    if releases.iter().any(|r| r.trim().is_empty()) {
        v.push(PopIssue { blocking: true, text: "Un nom de release est vide".into(), fix: None });
    }
    let mut seen: Vec<&String> = Vec::new();
    for r in releases {
        if seen.iter().any(|s| s.eq_ignore_ascii_case(r)) {
            v.push(PopIssue { blocking: true, text: format!("Deux éléments donneraient la même release : {r}"), fix: None });
        }
        seen.push(r);
    }
    if action != "rename" {
        if cfg.post_mode == "cli" && !cfg.ngpost_exe.trim().is_empty() && !ngpost::exe_path(cfg).is_file() {
            v.push(PopIssue { blocking: true, text: format!("ngPost.exe introuvable : {}", cfg.ngpost_exe), fix: settings("ngpost.exe") });
        }
        let conf = ngpost::read_conf(cfg);
        for w in ngpost::post_warnings(cfg, conf.as_ref()) {
            v.push(PopIssue { blocking: false, text: w, fix: settings("options du post") });
        }
        if let Some(h) = hist {
            if !force_dup {
                for r in releases {
                    if let Some(rec) = h.find_sent(r) {
                        v.push(PopIssue { blocking: false, text: format!("{r} a déjà été envoyée {} : elle {}", history::format_relative(rec.ts), if cfg.skip_duplicates { "sera refusée comme doublon (anti-doublon actif)" } else { "sera postée une seconde fois" }), fix: Some(("Voir l'historique".into(), PopAct::Go(Page::History))) });
                    }
                }
            }
        }
        for t in targets {
            if let Some(ic) = cfg.indexers.iter().find(|i| i.name.trim().eq_ignore_ascii_case(t.trim()) && i.active) {
                if ic.has_api() && ic.api_key.trim().is_empty() {
                    v.push(PopIssue { blocking: false, text: format!("{} : dépôt par API sans clé API (vérifie si l'indexer en demande une)", ic.name), fix: settings("indexers") });
                }
            }
        }
    }
    v
}

