/// Élément du lot qui n'est pas une vidéo (jeu, logiciel, album…) : traité comme contenu.
#[derive(Clone)]
struct OtherRow {
    path: PathBuf,
    size: u64,
    cat: String,
    name: String,
    edited: bool,
    selected: bool,
    state: RowState,
}

/// Dossier de série d'un lot : traité d'un bloc avec les réglages des séries.
#[derive(Clone)]
struct SeriesRow {
    path: PathBuf,
    summary: String,
    releases: Vec<String>,
    selected: bool,
    state: RowState,
}

/// Dossiers de série d'un dossier de lot : le dossier lui-même, ou ses sous-dossiers.
/// « Saison 1 », « S02 », « Season 3 » : seulement un numéro de saison, pas de titre.
/// (« Ma Serie Saison 1 » a un titre : c'est une série à part.)
fn pure_season(name: &str) -> bool {
    if crate::series::season_from_dir(name).is_none() {
        return false;
    }
    let l = name.to_lowercase();
    l.split(|c: char| !c.is_alphanumeric()).filter(|w| !w.is_empty()).all(|w| {
        w.chars().all(|c| c.is_ascii_digit())
            || ["saison", "season", "series", "temporada", "staffel", "stagione", "seizoen", "sezon", "specials", "special", "speciaux", "spéciaux", "bonus"].iter().any(|k| w == *k || w.strip_prefix(k).map(|r| r.chars().all(|c| c.is_ascii_digit())).unwrap_or(false))
            || w.strip_prefix('s').map(|r| !r.is_empty() && r.chars().all(|c| c.is_ascii_digit())).unwrap_or(false)
    })
}

/// Un sous-dossier « Saison 2 » appartient à la série du dossier parent ; un sous-dossier
/// « The Office (US) » est une série à part.
fn series_dirs_in(dir: &Path) -> Vec<PathBuf> {
    let mut subs: Vec<PathBuf> = std::fs::read_dir(dir)
        .map(|rd| {
            rd.flatten()
                .map(|e| e.path())
                .filter(|p| {
                    let n = prep::file_name(p);
                    p.is_dir() && !n.starts_with(['.', '_', '@']) && !pure_season(&n) && crate::disc::detect(p).is_none() && crate::series::looks_like_series(p)
                })
                .collect()
        })
        .unwrap_or_default();
    if !subs.is_empty() {
        subs.sort();
        return subs;
    }
    // le dossier lui-même est une série si toutes ses vidéos directes sont des épisodes
    let loose = prep::list_videos(dir, false);
    let all_episodes = loose.iter().all(|f| crate::series::parse_episode(&f.file_stem().map(|x| x.to_string_lossy().to_string()).unwrap_or_default()).is_some());
    if crate::series::looks_like_series(dir) && all_episodes && crate::disc::detect(dir).is_none() {
        vec![dir.to_path_buf()]
    } else {
        Vec::new()
    }
}

/// Fichiers qui accompagnent une vidéo (pas des contenus à part entière).
const SIDECAR_EXT: &[&str] = &["srt", "sub", "idx", "ass", "ssa", "vtt", "sup", "nfo", "txt", "jpg", "jpeg", "png", "sfv", "nzb", "xml", "url", "db", "ini", "par2"];

/// Autres contenus d'un dossier (premier niveau) : fichiers qui ne sont ni des vidéos ni leurs
/// fichiers d'accompagnement, dossiers sans vidéo.
fn other_items(dir: &Path) -> Vec<PathBuf> {
    let Ok(rd) = std::fs::read_dir(dir) else { return Vec::new() };
    let mut v: Vec<PathBuf> = rd
        .flatten()
        .map(|e| e.path())
        .filter(|p| {
            let n = prep::file_name(p);
            if n.starts_with('.') || n.starts_with('_') || n.starts_with('@') {
                return false;
            }
            if p.is_dir() {
                prep::list_videos(p, true).is_empty() && !crate::content::files_of(p).is_empty()
            } else {
                let ext = p.extension().map(|e| e.to_string_lossy().to_lowercase()).unwrap_or_default();
                !prep::is_video(p) && !SIDECAR_EXT.contains(&ext.as_str())
            }
        })
        .collect();
    v.sort();
    v
}

