// ================================================================== Lancement

pub fn run(cfg: Config, cfg_path: PathBuf, hist_path: PathBuf, hidden: bool) {
    // lancé avec Windows (--tray), ou réglage « même quand je l'ouvre moi-même »
    let start_hidden = (hidden || cfg.start_in_tray) && crate::tray::available();
    if start_hidden {
        crate::tray::keep_hidden_at_start();
    }
    // lancement avec Windows d'une ancienne version (sans --tray) ou exécutable déplacé
    thread::spawn(|| {
        if crate::tray::refresh_autostart() {
            crate::notify::record("Lancement avec Windows mis à jour : démarrage dans la zone de notification");
        }
    });
    let options = eframe::NativeOptions {
        viewport: egui::ViewportBuilder::default()
            .with_title(crate::APP_NAME)
            .with_inner_size([1200.0, 780.0])
            .with_min_inner_size([960.0, 620.0])
            .with_icon(app_icon()),
        ..Default::default()
    };
    let _ = eframe::run_native(
        crate::APP_NAME,
        options,
        Box::new(move |cc| {
            let (regular, semibold) = system_fonts();
            set_theme(&cfg.theme);
            setup(&cc.egui_ctx, regular, semibold, &cfg.accent);
            let mut app = App::new(cc.egui_ctx.clone(), cfg, cfg_path, hist_path);
            app.start_hidden = start_hidden;
            Ok(Box::new(app))
        }),
    );
}

/// Segoe UI sous Windows (police du système), sinon Inter si présente, sinon police egui.
fn system_fonts() -> (Option<Vec<u8>>, Option<Vec<u8>>) {
    let candidates: &[(&str, &str)] = &[
        ("C:\\Windows\\Fonts\\segoeui.ttf", "C:\\Windows\\Fonts\\seguisb.ttf"),
        ("/usr/share/fonts/opentype/inter/Inter-Regular.otf", "/usr/share/fonts/opentype/inter/Inter-SemiBold.otf"),
    ];
    for (r, s) in candidates {
        if let Ok(rb) = std::fs::read(r) {
            return (Some(rb), std::fs::read(s).ok());
        }
    }
    (None, None)
}

pub fn setup(ctx: &egui::Context, regular: Option<Vec<u8>>, semibold: Option<Vec<u8>>, accent: &str) {
    let mut fonts = egui::FontDefinitions::default();
    let mut prop = fonts.families.get(&FontFamily::Proportional).cloned().unwrap_or_default();
    if let Some(b) = regular {
        fonts.font_data.insert("ui".into(), Arc::new(egui::FontData::from_owned(b)));
        prop.insert(0, "ui".into());
    }
    let mut semi_family = prop.clone();
    if let Some(b) = semibold {
        fonts.font_data.insert("ui-semibold".into(), Arc::new(egui::FontData::from_owned(b)));
        semi_family.insert(0, "ui-semibold".into());
    }
    fonts.families.insert(FontFamily::Proportional, prop);
    fonts.families.insert(FontFamily::Name("semibold".into()), semi_family);
    // police à chasse fixe du système (thèmes Terminal et Ambre, journaux)
    for f in ["C:\\Windows\\Fonts\\CascadiaMono.ttf", "C:\\Windows\\Fonts\\consola.ttf", "/usr/share/fonts/truetype/dejavu/DejaVuSansMono.ttf"] {
        if let Ok(b) = std::fs::read(f) {
            fonts.font_data.insert("ui-mono".into(), Arc::new(egui::FontData::from_owned(b)));
            if let Some(m) = fonts.families.get_mut(&FontFamily::Monospace) {
                m.insert(0, "ui-mono".into());
            }
            break;
        }
    }
    ctx.set_fonts(fonts);
    apply_theme(ctx, accent_color(accent));
}

fn apply_theme(ctx: &egui::Context, accent: Color32) {
    let t = pal();
    ACCENT_RGB.store(((accent.r() as u32) << 16) | ((accent.g() as u32) << 8) | accent.b() as u32, std::sync::atomic::Ordering::Relaxed);
    let kind = if t.dark { egui::Theme::Dark } else { egui::Theme::Light };
    ctx.set_theme(kind);
    let mut v = if t.dark { egui::Visuals::dark() } else { egui::Visuals::light() };
    v.panel_fill = t.bg;
    v.window_fill = t.card;
    v.window_stroke = Stroke::new(t.stroke, t.border);
    v.extreme_bg_color = t.input;
    v.faint_bg_color = mix(t.card, t.card_hi, 0.5);
    v.code_bg_color = t.input;
    v.hyperlink_color = accent;
    v.override_text_color = None;
    v.warn_fg_color = t.orange;
    v.error_fg_color = t.red;
    v.selection.bg_fill = if t.dark { accent.gamma_multiply(0.55) } else { mix(t.card, accent, 0.3) };
    v.selection.stroke = Stroke::new(1.0_f32, t.text);
    v.window_corner_radius = cr(14);
    v.menu_corner_radius = cr(10);
    let shadow = Shadow { offset: [0, 8], blur: 28, spread: 0, color: Color32::from_black_alpha(if t.dark { 130 } else { 40 }) };
    v.window_shadow = shadow;
    v.popup_shadow = shadow;

    v.widgets.noninteractive.bg_fill = t.card;
    v.widgets.noninteractive.weak_bg_fill = t.card;
    v.widgets.noninteractive.bg_stroke = Stroke::new(t.stroke, t.border);
    v.widgets.noninteractive.fg_stroke = Stroke::new(1.0_f32, t.text);

    v.widgets.inactive.bg_fill = t.card_hi;
    v.widgets.inactive.weak_bg_fill = t.card_hi;
    v.widgets.inactive.bg_stroke = Stroke::new(t.stroke, mix(t.border, t.text, 0.12));
    v.widgets.inactive.fg_stroke = Stroke::new(1.0_f32, t.text);

    let hover = mix(t.card_hi, t.text, if t.dark { 0.06 } else { 0.05 });
    v.widgets.hovered.bg_fill = hover;
    v.widgets.hovered.weak_bg_fill = hover;
    v.widgets.hovered.bg_stroke = Stroke::new(t.stroke, accent.gamma_multiply(0.8));
    v.widgets.hovered.fg_stroke = Stroke::new(1.5_f32, t.text);
    v.widgets.hovered.expansion = 0.0;

    v.widgets.active.bg_fill = accent;
    v.widgets.active.weak_bg_fill = if t.dark { accent.gamma_multiply(0.45) } else { mix(t.card, accent, 0.35) };
    v.widgets.active.bg_stroke = Stroke::new(t.stroke, accent);
    v.widgets.active.fg_stroke = Stroke::new(1.5_f32, ink());
    v.widgets.active.expansion = 0.0;

    v.widgets.open.bg_fill = t.card_hi;
    v.widgets.open.weak_bg_fill = t.card_hi;
    v.widgets.open.bg_stroke = Stroke::new(t.stroke, accent);

    for w in [
        &mut v.widgets.noninteractive,
        &mut v.widgets.inactive,
        &mut v.widgets.hovered,
        &mut v.widgets.active,
        &mut v.widgets.open,
    ] {
        w.corner_radius = cr(8);
    }
    ctx.set_visuals_of(kind, v);

    ctx.style_mut_of(kind, |s| {
        s.spacing.item_spacing = vec2(8.0, 8.0);
        s.spacing.button_padding = vec2(14.0, 6.0);
        s.spacing.interact_size.y = 30.0;
        s.spacing.combo_width = 180.0;
        let body = if t.mono { FontId::monospace(13.5) } else { FontId::proportional(14.5) };
        s.text_styles.insert(egui::TextStyle::Body, body.clone());
        s.text_styles.insert(egui::TextStyle::Button, body);
        s.text_styles.insert(egui::TextStyle::Small, if t.mono { FontId::monospace(11.5) } else { FontId::proportional(12.0) });
        s.text_styles.insert(egui::TextStyle::Monospace, FontId::monospace(13.0));
        s.text_styles.insert(egui::TextStyle::Heading, semi(22.0));
    });
}

/// Icône de l'application (128×128 RGBA, générée depuis assets/app.ico).
const ICON_RGBA: &[u8] = include_bytes!("../assets/icon-128.rgba");

fn app_icon() -> egui::IconData {
    egui::IconData { rgba: ICON_RGBA.to_vec(), width: 128, height: 128 }
}

// ================================================================ Composants

fn card<R>(ui: &mut Ui, add: impl FnOnce(&mut Ui) -> R) -> R {
    let t = pal();
    Frame::new()
        .fill(t.card)
        .stroke(Stroke::new(t.stroke, t.border))
        .shadow(if t.shadow { Shadow { offset: [0, 2], blur: 12, spread: 0, color: Color32::from_black_alpha(22) } } else { Shadow::NONE })
        .corner_radius(cr(14))
        .inner_margin(Margin::same(18))
        .show(ui, |ui| {
            ui.set_width(ui.available_width());
            add(ui)
        })
        .inner
}

/// Vignette d'aperçu d'un thème : fond, barre latérale, carte, accent, nom.
fn theme_tile(ui: &mut Ui, t: &Theme, sel: bool) -> egui::Response {
    let (rect, resp) = ui.allocate_exact_size(vec2(150.0, 118.0), Sense::click());
    let p = ui.painter();
    let prev = Rect::from_min_size(rect.min, vec2(rect.width(), 86.0));
    let rr = |r: f32| CornerRadius::same((r * t.round).round() as u8);
    p.rect_filled(prev, rr(10.0), t.bg);
    // barre latérale
    let side = Rect::from_min_max(prev.min, pos2(prev.min.x + 34.0, prev.max.y));
    p.rect_filled(side, CornerRadius { nw: rr(10.0).nw, sw: rr(10.0).sw, ne: 0, se: 0 }, t.sidebar);
    p.rect_filled(Rect::from_min_size(side.min + vec2(9.0, 10.0), vec2(16.0, 16.0)), rr(5.0), t.accent);
    for k in 0..3 {
        let y = side.min.y + 36.0 + k as f32 * 13.0;
        let c = if k == 0 { t.text } else { t.faint };
        p.rect_filled(Rect::from_min_size(pos2(side.min.x + 8.0, y), vec2(18.0, 4.0)), rr(2.0), c);
    }
    // carte
    let card = Rect::from_min_max(pos2(side.max.x + 9.0, prev.min.y + 10.0), pos2(prev.max.x - 9.0, prev.max.y - 10.0));
    if t.shadow {
        p.rect_filled(card.translate(vec2(0.0, 1.5)), rr(7.0), Color32::from_black_alpha(25));
    }
    p.rect_filled(card, rr(7.0), t.card);
    p.rect_stroke(card, rr(7.0), Stroke::new(t.stroke, t.border), egui::StrokeKind::Inside);
    let font = if t.mono { FontId::monospace(10.5) } else { FontId::proportional(11.0) };
    p.text(card.min + vec2(8.0, 6.0), Align2::LEFT_TOP, "Aa", font.clone(), t.text);
    p.rect_filled(Rect::from_min_size(card.min + vec2(30.0, 10.0), vec2(card.width() - 40.0, 4.0)), rr(2.0), t.muted);
    p.rect_filled(Rect::from_min_size(card.min + vec2(8.0, 25.0), vec2(card.width() - 16.0, 4.0)), rr(2.0), t.faint);
    // boutons : accent + vert, orange, rouge
    let by = card.max.y - 20.0;
    p.rect_filled(Rect::from_min_size(pos2(card.min.x + 8.0, by), vec2(36.0, 12.0)), rr(4.0), t.accent);
    for (k, c) in [t.green, t.orange, t.red].into_iter().enumerate() {
        p.circle_filled(pos2(card.min.x + 54.0 + k as f32 * 11.0, by + 6.0), 3.5, c);
    }
    // cadre de sélection
    let frame_col = if sel { ui.visuals().widgets.active.bg_fill } else if resp.hovered() { pal().muted } else { pal().border };
    p.rect_stroke(prev.expand(if sel { 2.5 } else { 0.5 }), rr(11.0), Stroke::new(if sel { 2.0_f32 } else { 1.0 }, frame_col), egui::StrokeKind::Outside);
    let name_col = if sel { pal().text } else { pal().muted };
    p.text(pos2(rect.min.x + 2.0, prev.max.y + 8.0), Align2::LEFT_TOP, format!("{}{}", if sel { "✔ " } else { "" }, t.name), semi(13.0), name_col);
    p.text(pos2(rect.max.x - 2.0, prev.max.y + 10.0), Align2::RIGHT_TOP, if t.dark { "sombre" } else { "clair" }, fp(11.0), pal().faint);
    resp
}

fn card_title(ui: &mut Ui, title: &str, subtitle: &str) {
    ui.label(RichText::new(title).font(semi(15.5)).color(pal().text));
    if !subtitle.is_empty() {
        ui.label(RichText::new(subtitle).size(12.5).color(pal().muted));
    }
    ui.add_space(6.0);
}

fn page_header(ui: &mut Ui, title: &str, subtitle: &str, actions: impl FnOnce(&mut Ui)) {
    if ui.available_width() < 820.0 {
        // fenêtre étroite : actions sous le titre
        ui.label(RichText::new(title).font(semi(25.0)).color(pal().text));
        ui.label(RichText::new(subtitle).size(13.5).color(pal().muted));
        ui.add_space(6.0);
        ui.horizontal(actions);
    } else {
        ui.horizontal(|ui| {
            ui.with_layout(Layout::right_to_left(Align::Min), |ui| {
                // marge pour la barre de défilement
                ui.add_space(10.0);
                ui.horizontal(actions);
                ui.add_space(12.0);
                ui.with_layout(Layout::top_down(Align::Min), |ui| {
                    ui.label(RichText::new(title).font(semi(25.0)).color(pal().text));
                    ui.add(egui::Label::new(RichText::new(subtitle).size(13.5).color(pal().muted)).wrap());
                });
            });
        });
    }
    ui.add_space(16.0);
}

fn btn_primary(ui: &mut Ui, text: &str, color: Color32, enabled: bool) -> egui::Response {
    ui.add_enabled(
        enabled,
        egui::Button::new(RichText::new(text).font(semi(14.0)).color(ink_on(color)))
            .fill(color)
            .stroke(Stroke::NONE)
            .corner_radius(cr(9))
            .min_size(vec2(0.0, 34.0)),
    )
    .on_hover_cursor(egui::CursorIcon::PointingHand)
}

fn btn(ui: &mut Ui, text: &str) -> egui::Response {
    ui.add(
        egui::Button::new(RichText::new(text).color(pal().text))
            .fill(pal().card_hi)
            .stroke(Stroke::new(1.0_f32, pal().border))
            .corner_radius(cr(9))
            .min_size(vec2(0.0, 34.0)),
    )
    .on_hover_cursor(egui::CursorIcon::PointingHand)
}

fn btn_small(ui: &mut Ui, text: &str) -> egui::Response {
    ui.add(
        egui::Button::new(RichText::new(text).size(13.0).color(pal().text))
            .fill(pal().card_hi)
            .stroke(Stroke::new(1.0_f32, pal().border))
            .corner_radius(cr(8))
            .min_size(vec2(0.0, 28.0)),
    )
    .on_hover_cursor(egui::CursorIcon::PointingHand)
}

fn badge(ui: &mut Ui, text: &str, color: Color32) {
    // un seul bloc, jamais coupé : la ligne passe à la suivante s'il ne tient pas (avant, le
    // texte se resserrait jusqu'à s'écrire lettre par lettre, à la verticale)
    let galley = ui.fonts(|f| f.layout_no_wrap(text.to_string(), semi(12.0), color));
    let size = galley.size() + vec2(18.0, 6.0);
    let (r, _) = ui.allocate_exact_size(size, Sense::hover());
    if ui.is_rect_visible(r) {
        ui.painter().rect_filled(r, cr(20), color.gamma_multiply(0.16));
        ui.painter().galley(pos2(r.min.x + 9.0, r.center().y - galley.size().y / 2.0), galley, color);
    }
}

/// Pastille dessinée directement (lignes de tableaux). Renvoie la largeur occupée.
fn paint_badge(p: &egui::Painter, left_center: egui::Pos2, text: &str, color: Color32) -> f32 {
    let galley = p.layout_no_wrap(text.to_string(), semi(12.0), color);
    let size = galley.size() + vec2(18.0, 8.0);
    let r = Rect::from_min_size(pos2(left_center.x, left_center.y - size.y / 2.0), size);
    p.rect_filled(r, cr(12), color.gamma_multiply(0.16));
    p.galley(r.min + vec2(9.0, 4.0), galley, color);
    size.x
}

fn banner(ui: &mut Ui, color: Color32, icon: &str, text: &str) {
    Frame::new()
        .fill(color.gamma_multiply(0.10))
        .stroke(Stroke::new(1.0_f32, color.gamma_multiply(0.45)))
        .corner_radius(cr(10))
        .inner_margin(Margin::symmetric(14, 10))
        .show(ui, |ui| {
            ui.set_width(ui.available_width());
            ui.horizontal(|ui| {
                ui.label(RichText::new(icon).size(15.0).color(color));
                ui.add(egui::Label::new(RichText::new(text).color(pal().text)).wrap());
            });
        });
}

fn toggle(ui: &mut Ui, on: &mut bool, label: &str, help: &str, accent: Color32) -> egui::Response {
    ui.horizontal(|ui| {
        let (rect, mut resp) = ui.allocate_exact_size(vec2(40.0, 22.0), Sense::click());
        if resp.clicked() {
            *on = !*on;
            resp.mark_changed();
        }
        let t = ui.ctx().animate_bool(resp.id, *on);
        let p = ui.painter();
        p.rect_filled(rect, cr(11), pal().faint.lerp_to_gamma(accent, t));
        let x = egui::lerp((rect.left() + 11.0)..=(rect.right() - 11.0), t);
        p.rect_filled(Rect::from_center_size(pos2(x, rect.center().y), vec2(16.0, 16.0)), cr(8), Color32::WHITE);
        ui.add_space(4.0);
        ui.vertical(|ui| {
            ui.label(RichText::new(label).color(pal().text));
            if !help.is_empty() {
                ui.label(RichText::new(help).size(12.0).color(pal().muted));
            }
        });
        resp.on_hover_cursor(egui::CursorIcon::PointingHand)
    })
    .inner
}

/// Case à cocher dessinée (carré arrondi, coche blanche sur fond d'accent).
fn check(ui: &mut Ui, on: &mut bool, enabled: bool, accent: Color32) {
    let (rect, resp) = ui.allocate_exact_size(vec2(20.0, 20.0), if enabled { Sense::click() } else { Sense::hover() });
    if enabled && resp.clicked() {
        *on = !*on;
    }
    let p = ui.painter();
    let r = Rect::from_center_size(rect.center(), vec2(18.0, 18.0));
    if *on {
        p.rect_filled(r, cr(5), if enabled { accent } else { accent.gamma_multiply(0.4) });
        p.text(r.center(), Align2::CENTER_CENTER, "✔", fp(12.0), ink());
    } else {
        p.rect_filled(r, cr(5), pal().input);
        let border = if enabled && resp.hovered() { accent } else { mix(pal().border, pal().text, 0.25) };
        p.rect_stroke(r, cr(5), Stroke::new(1.5_f32, border), StrokeKind::Inside);
    }
    if enabled {
        resp.on_hover_cursor(egui::CursorIcon::PointingHand);
    }
}

fn empty_state(ui: &mut Ui, icon: &str, title: &str, sub: &str) {
    ui.add_space(30.0);
    ui.vertical_centered(|ui| {
        ui.label(RichText::new(icon).size(40.0).color(pal().faint));
        ui.add_space(6.0);
        ui.label(RichText::new(title).font(semi(17.0)).color(pal().text));
        ui.label(RichText::new(sub).color(pal().muted));
    });
    ui.add_space(30.0);
}

