                ui.label(RichText::new(if cv("GEN_FROM").is_some() { "vide = aléatoire à chaque post (GEN_FROM)" } else { "vide = ngPost.conf / aléatoire" }).size(12.0).color(pal().faint));
                ui.end_row();
