    #[allow(dead_code)]
    pub fn demo_idx_tools(&mut self, k: usize, q: &str) {
        let i = self.cfg.indexers[k].clone();
        let l = crate::search::lookup(&i, &[q.to_string()]);
        let p = crate::apidef::profile(&i);
        let n = p.requests.iter().position(|r| r.id == "search").unwrap_or(0);
        let r = crate::apidef::send(&i, &p, &p.requests[n], &[("release".into(), q.into())]);
        let t = self.idx_tools.entry(i.name.trim().to_string()).or_default();
        t.query = q.into();
        t.search = Some(Ok(l));
        t.sel = n;
        t.reply = Some(r);
        t.section = std::env::var("APISECTION").ok().and_then(|v| v.parse().ok()).unwrap_or(0);
        if std::env::var("APIPRESETS").is_ok() {
            t.preset_open = true;
        }
        if t.section == 3 {
            if let Ok((c, _)) = crate::apidef::read_caps(&i, &p) {
                self.cfg.indexers[k].api.caps = c;
            }
        }
        self.idx_edit = Some(k);
        self.idx_tab = 1;
        self.page = Page::Settings;
        self.set_query = "§Indexers".into();
        if let Ok(f) = std::env::var("FREEREQ") {
            if let Some(t) = self.idx_tools.get_mut(self.cfg.indexers[k].name.trim()) {
                t.free = f;
            }
        }
    }

