    /// Démo : outils de réglage d'un indexer, avec une doc d'API lue.
    #[allow(dead_code)]
    pub fn demo_idx_setup(&mut self, k: usize, doc: &str) {
        let name = self.cfg.indexers[k].name.trim().to_string();
        let text = std::fs::read_to_string(doc).unwrap_or_default();
        let t = self.idx_tools.entry(name).or_default();
        t.doc = Some(crate::apidoc::analyze(&text));
        t.doc_text = text;
        t.auto_log = vec!["✔ Capacités lues : 32 catégories, 41 groupes".into(), "✔ Clé acceptée (recherche test)".into(), "✖ t=nzbadd : HTTP 405 — l'envoi n'est pas sur /api".into(), "✔ Adresse d'envoi trouvée : https://lien.indexer/v1/upload".into()];
        // indexer réglé comme après la configuration automatique (recherche /api, envoi /v1)
        if let Ok(caps) = std::env::var("CAPS") {
            let body = std::fs::read_to_string(caps).unwrap_or_default();
            if let Ok(c) = crate::apidef::parse_caps(&body) {
                let i = &mut self.cfg.indexers[k];
                i.api = crate::apidef::Profile::default();
                i.mode = "rest".into();
                i.api_url = "https://api.indexer2.example/api".into();
                i.api_key = "DEMO-KEY-123456".into();
                i.rest_url = "https://indexer2.example".into();
                i.rest_path = "https://indexer2.example/v1/upload".into();
                i.auth = "query".into();
                i.auth_name = "apikey".into();
                i.cat_list = c.cats.clone();
                i.groups = c.groups.clone();
                i.groups_rule = "add".into();
                i.api.kind = "newznab".into();
                i.api.requests = crate::apidef::newznab_requests(&c);
                i.api.caps = c.clone();
                crate::upload::fill_categories(i, &c.cats, false);
                i.group_rules = vec![("2045".into(), "alt.binaries.hdtv.x264".into()), ("5000".into(), "alt.binaries.teevee".into())];
                i.api.user_agent = "browser".into();
            }
        }
        self.page = Page::Settings;
        self.set_query = "§Indexers".into();
        self.idx_edit = Some(k);
        self.idx_tab = 0;
    }

