trait StatusIcon {
    fn status_icon(&self) -> &'static str;
}

impl StatusIcon for Record {
    fn status_icon(&self) -> &'static str {
        match self.status {
            Status::Sent => "✔",
            Status::Quarantine => "⚠",
            Status::Failed => "✖",
        }
    }
}

impl eframe::App for App {
    /// Fond de la fenêtre aux couleurs du thème (visible un instant pendant un redimensionnement).
    fn clear_color(&self, _visuals: &egui::Visuals) -> [f32; 4] {
        pal().bg.to_normalized_gamma_f32()
    }

    fn update(&mut self, ctx: &egui::Context, _frame: &mut eframe::Frame) {
        prep::set_detail(self.cfg.log_detail);
        crate::apidef::set_ua_global(&self.cfg.net_ua);
        if self.first_frame {
            self.first_frame = false;
            if self.start_hidden {
                // icône créée ici ; le fil de keep_hidden_at_start recache la fenêtre quand
                // eframe la rend visible après cette première image
                self.to_tray();
                ctx.request_repaint();
            }
        }
        // fermeture de la fenêtre : zone de notification, question, ou sortie
        if ctx.input(|i| i.viewport().close_requested()) && !self.quitting {
            let tray = crate::tray::available();
            match self.cfg.close_action.as_str() {
                "tray" if tray => {
                    ctx.send_viewport_cmd(egui::ViewportCommand::CancelClose);
                    self.to_tray();
                }
                "quit" | "tray" => {
                    if let Some(work) = self.busy_text() {
                        ctx.send_viewport_cmd(egui::ViewportCommand::CancelClose);
                        self.close_dialog = Some(Some(work));
                    }
                }
                _ => {
                    ctx.send_viewport_cmd(egui::ViewportCommand::CancelClose);
                    self.close_dialog = Some(self.busy_text());
                }
            }
        }
        if crate::tray::available() {
            // pendant un post, l'infobulle est tenue à jour par le fil de post (débit, temps restant)
            if self.post_cur.is_none() {
                let st = if self.watching() { "surveillance active".to_string() } else { String::new() };
                crate::tray::set_status(&st);
            }
            crate::tray::set_notify(self.cfg.tray_notify);
        }
        // retour dans la fenêtre (après le navigateur ou l'explorateur) : on note l'instant
        let refocus = ctx.input(|i| i.events.iter().any(|e| matches!(e, egui::Event::WindowFocused(true))));
        if refocus {
            self.focus_at = ctx.input(|i| i.time);
            // fenêtre réaffichée (barre des tâches, zone de notification) : quelques images fraîches
            self.resize_burst = self.resize_burst.max(6);
        }
        self.pump();
        // Ctrl+F depuis n'importe quelle page : recherche des réglages (toujours visible en haut)
        if ctx.input_mut(|i| i.consume_key(egui::Modifiers::COMMAND, egui::Key::F)) {
            self.page = Page::Settings;
            ctx.memory_mut(|m| m.request_focus(egui::Id::new("settings_search")));
        }
        if ctx.input_mut(|i| i.consume_key(egui::Modifiers::COMMAND, egui::Key::S)) {
            self.save_now();
        }
        self.autosave();
        // fenêtre invisible (zone de notification, ou réduite) : rien n'est dessiné, et surtout
        // aucune image n'est demandée — Windows ne la livrerait jamais à une fenêtre cachée et
        // eframe tournerait à vide en l'attendant (les 12-13 % de processeur). Les événements
        // des fils de fond sont traités ci-dessus par `pump`, à chaque battement (2 s).
        let minimized = ctx.input(|i| i.viewport().minimized.unwrap_or(false));
        crate::tray::set_minimized(minimized);
        if crate::tray::in_background() {
            return;
        }
        self.refresh_caches();
        self.handle_drops();
        // animation : les valeurs affichées rejoignent la mesure en douceur, image par image
        let dt = ctx.input(|i| i.stable_dt).clamp(0.0, 0.1);
        if let Some(c) = &mut self.post_cur {
            let k = 1.0 - (-dt as f64 * 3.0).exp();
            c.disp_bps += (c.cur_bps.unwrap_or(0.0) - c.disp_bps) * k;
            let target = c.pct.map(|p| p as f32 / 100.0).unwrap_or(0.0);
            c.disp_frac += (target - c.disp_frac) * k as f32;
        }
        // fenêtre agrandie, restaurée, plein écran ou redimensionnée : on redessine plusieurs
        // images d'affilée à la nouvelle taille (sinon Windows peut garder l'ancienne image,
        // centrée dans un cadre blanc)
        let win = ctx.input(|i| (i.screen_rect(), i.viewport().maximized.unwrap_or(false), i.viewport().fullscreen.unwrap_or(false)));
        if win != self.last_win {
            self.last_win = win;
            self.resize_burst = 12;
        }
        if self.resize_burst > 0 {
            self.resize_burst = self.resize_burst.saturating_sub(1);
            ctx.request_repaint();
        } else if self.post_cur.is_some() || !self.progress.is_empty() {
            // post ou copie en cours : barre, débit et courbe en direct fluides (30 images/s)
            ctx.request_repaint_after(Duration::from_millis(33));
        } else if self.busy_text().is_some() || self.dl_active() {
            // autre travail en cours (téléchargements, dépôts, rapports…) : les barres glissent
            // d'elles-mêmes (animation d'egui), les compteurs avancent 4 fois par seconde
            ctx.request_repaint_after(Duration::from_millis(250));
        } else {
            // au repos : une image par seconde (heures relatives, état) ; tout événement d'un
            // fil de fond redessine aussitôt
            ctx.request_repaint_after(Duration::from_millis(1000));
        }

        egui::SidePanel::left("nav")
            .exact_width(236.0)
            .resizable(false)
            .show_separator_line(false)
            .frame(Frame::new().fill(pal().sidebar).inner_margin(Margin { left: 14, right: 14, top: 18, bottom: 14 }).stroke(Stroke::new(1.0_f32, pal().border)))
            .show(ctx, |ui| self.sidebar(ui));

        if self.page == Page::History && self.h_selected.is_some() {
            egui::SidePanel::right("details")
                .exact_width(340.0)
                .resizable(false)
                .show_separator_line(false)
                .frame(Frame::new().fill(pal().sidebar).inner_margin(Margin::same(20)).stroke(Stroke::new(1.0_f32, pal().border)))
                .show(ctx, |ui| self.history_details(ui));
        }

        // grand écran : la place vide à droite montre ce qui est en cours (téléchargements,
        // reposts, post, surveillance)
        if ctx.screen_rect().width() >= 1640.0 && !(self.page == Page::History && self.h_selected.is_some()) {
            egui::SidePanel::right("activity")
                .exact_width(330.0)
                .resizable(false)
                .show_separator_line(false)
                .frame(Frame::new().fill(pal().sidebar).inner_margin(Margin::same(18)).stroke(Stroke::new(1.0_f32, pal().border)))
                .show(ctx, |ui| egui::ScrollArea::vertical().id_salt("activity_panel").show(ui, |ui| self.activity_panel(ui)));
        }

        let page = self.page;
        egui::CentralPanel::default()
            .frame(Frame::new().fill(pal().bg).inner_margin(Margin::symmetric(28, 22)))
            .show(ctx, |ui| {
                self.activity_strip(ui);
                match page {
                Page::History => self.page_history(ui),
                Page::Journal => self.page_journal(ui),
                _ => {
                    let mut area = egui::ScrollArea::vertical().id_salt(("page", page as u8)).auto_shrink([false, false]);
                    if page == Page::Settings {
                        self.settings_head(ui);
                        if std::mem::take(&mut self.set_scroll_top) {
                            area = area.vertical_scroll_offset(0.0);
                        }
                    }
                    area.show(ui, |ui| match page {
                        Page::Dashboard => self.page_dashboard(ui),
                        Page::Manual => {
                            self.page_manual(ui);
                            self.api_trace_card(ui);
                        }
                        Page::Batch => {
                            self.page_batch(ui);
                            self.api_trace_card(ui);
                        }
                        Page::Series => {
                            self.page_series(ui);
                            self.api_trace_card(ui);
                        }
                        Page::Content => {
                            self.page_content(ui);
                            self.api_trace_card(ui);
                        }
                        Page::Quarantine => self.page_quarantine(ui),
                        Page::Indexer => self.page_indexer(ui),
                        Page::Nzb => {
                            self.page_nzb(ui);
                            self.api_trace_card(ui);
                        }
                        Page::Downloads => self.page_downloads(ui),
                        Page::Search => self.page_search(ui),
                        Page::Reports => self.page_reports(ui),
                        Page::Settings => self.page_settings(ui),
                        Page::History | Page::Journal => {}
                    });
                }
                }
            });

        self.report_window(ctx);
        self.help_window(ctx);
        self.close_window(ctx);
        self.log_windows(ctx);
        self.doc_window(ctx);
        self.toasts_ui(ctx);
        self.saved_pill(ctx);
        self.drop_overlay(ctx);
        self.confirm_dialog(ctx);
        self.reports_window(ctx);
        self.popup_window(ctx);
        self.wizard_window(ctx);
    }
}

