#[cfg(test)]
mod tests {
    use super::*;

    /// Contrôles avant un traitement manuel : ce qui bloque, ce qui avertit.
    #[test]
    fn controles_avant_traitement() {
        let cfg = Config { ngpost_dir: "/sortie".into(), ..Default::default() };
        // renommer seulement : rien à poster, rien de bloquant
        assert!(send_issues(&cfg, "rename", &[], None, &["A-GRP".into()], None, false).iter().all(|i| !i.blocking));
        // deux éléments, même release : bloquant
        let v = send_issues(&cfg, "rename", &[], None, &["A-GRP".into(), "a-grp".into()], None, false);
        assert!(v.iter().any(|i| i.blocking && i.text.contains("même release")));
        // nom vide, dossier de sortie absent : bloquants
        let none = Config::default();
        let v = send_issues(&none, "rename", &[], None, &[String::new()], None, false);
        assert!(v.iter().filter(|i| i.blocking).count() >= 2);
        // poster sans ngPost.exe : bloquant, avec le réglage à ouvrir
        let post = Config { ngpost_dir: "/sortie".into(), post_mode: "cli".into(), ..Default::default() };
        let v = send_issues(&post, "post", &[], None, &["A-GRP".into()], None, false);
        assert!(v.iter().any(|i| i.blocking && i.fix.is_some()));
    }

    /// Un repost en échec garde le dossier téléchargé pour pouvoir réessayer.
    #[test]
    fn dossier_d_un_repost_en_echec() {
        let d = std::env::temp_dir().join("nzbff-repost-dir-test");
        std::fs::create_dir_all(&d).unwrap();
        let p = d.display().to_string();
        assert_eq!(repost_dir(&p), Some(d.clone()));
        assert_eq!(repost_dir(&format!("aucune vidéo{REPOST_DIR}{p}")), Some(d.clone()));
        assert_eq!(repost_dir("téléchargement en échec : CRC"), None);
        assert_eq!(repost_dir(&format!("raison{REPOST_DIR}/n/existe/pas")), None);
        let _ = std::fs::remove_dir_all(&d);
    }

    /// Les choix d'un traitement manuel remplacent les valeurs par défaut pour ce traitement
    /// seulement ; sans choix, les valeurs par défaut restent.
    #[test]
    fn choix_nfo_mediainfo_par_traitement() {
        let mut cfg = Config { nfo_create: false, ..Default::default() };
        cfg.indexers = vec![prep::IndexerCfg { send_mi: true, send_nfo: true, ..prep::IndexerCfg::new("A") }];
        let base = JobFiles::from_cfg(&cfg);
        let mut c = cfg.clone();
        base.apply(&mut c);
        assert_eq!(c, cfg);
        let jf = JobFiles { nfo_create: Some(true), nfo_keep: false, nfo_send: false, mi_send: Some(false), cats: vec![("A".into(), "5342".into())], nfo_text: Some("MON NFO".into()), ..JobFiles::from_cfg(&cfg) };
        let mut c = cfg.clone();
        jf.apply(&mut c);
        assert!(c.nfo_create && !c.nfo_keep && !c.nfo_send && !c.indexers[0].send_mi);
        assert_eq!(c.cat_force, vec![("A".to_string(), "5342".to_string())]);
        assert_eq!(c.nfo_override.as_deref(), Some("MON NFO"));
        assert!(c.mi_override.is_none() && c.bd_override.is_none());
        let mut c = cfg.clone();
        JobFiles { nfo_create: Some(false), ..base.clone() }.apply(&mut c);
        // la case « nfo » d'un indexer ne force plus la création : seul nfo_create décide
        assert!(!c.nfo_create, "aucun NFO créé");
    }

    #[test]
    fn filtre_des_journaux() {
        let mut p = LogPrefs::default();
        assert!(p.accepts("Connexion OK", false));
        p.filter = "newshosting".into();
        assert!(p.accepts("Test Newshosting (news.newshosting.com:563)", false));
        assert!(!p.accepts("Test Eweka", false));
        p.filter.clear();
        p.issues = true;
        assert!(!p.accepts("ok", false) && p.accepts("✖ erreur", true));
    }
}
